package in.asmj.ride.web;
import in.asmj.ride.model.*;import in.asmj.ride.repo.*;import in.asmj.ride.service.FareCalculator;
import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.http.ResponseEntity;
import java.time.*;import java.util.*;import java.security.SecureRandom;
import org.springframework.beans.factory.annotation.Value;
@Controller
public class RideController {
 private final UserAccountRepository users; private final RideBookingRepository rides; private final VehicleRepository vehicles; private final FareRuleRepository fareRules; private final FareCalculator fareCalculator; private final ServiceCityRepository cities; private final PaymentRecordRepository payments; private final SecureRandom random=new SecureRandom();
 public RideController(UserAccountRepository u,RideBookingRepository r,VehicleRepository v,FareRuleRepository f,FareCalculator c,ServiceCityRepository cities,PaymentRecordRepository payments){users=u;rides=r;vehicles=v;fareRules=f;fareCalculator=c;this.cities=cities;this.payments=payments;}
 private UserAccount me(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 private FareRule fare(){return fareRules.findById("default").orElseGet(()->fareRules.save(new FareRule()));}
 private boolean hasActiveAssignment(UserAccount u){return rides.findByAssignedDriverIdOrderByCreatedAtDesc(u.getId()).stream().anyMatch(x->List.of("ACCEPTED","ASSIGNED","IN_PROGRESS").contains(x.getStatus()))||rides.findAll().stream().anyMatch(x->u.getId().equals(x.getReturnAssignedDriverId())&&("ACCEPTED".equals(x.getReturnLegStatus())||"IN_PROGRESS".equals(x.getReturnLegStatus())));}
 @GetMapping("/customer") String customer(Authentication a,Model m){UserAccount u=me(a);m.addAttribute("name",u.getName());m.addAttribute("user",u);m.addAttribute("rides",rides.findByCustomerIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("fareRule",fare());m.addAttribute("cities",cities.findByActiveTrueOrderByCityAsc());return "customer";}
 @PostMapping("/rides/book") String book(Authentication a,@RequestParam String pickup,@RequestParam String destination,@RequestParam String pickupCityId,@RequestParam String pickupPinCode,@RequestParam String destinationCityId,@RequestParam String destinationPinCode,@RequestParam(defaultValue="ONE_WAY") String journeyType,@RequestParam(required=false) String returnAt,@RequestParam String category,@RequestParam String tripType,@RequestParam(required=false) String scheduledAt,@RequestParam String paymentMethod,@RequestParam(required=false,defaultValue="0") double distanceKm){
  UserAccount u=me(a);if(pickup.isBlank()||destination.isBlank()||pickup.length()>250||destination.length()>250||pickup.trim().equalsIgnoreCase(destination.trim()))return "redirect:/customer?error=locations";
  if(!List.of("CAR","AUTO","BIKE","OTHER").contains(category)||!List.of("IMMEDIATE","SCHEDULED").contains(tripType)||!List.of("CASH","UPI").contains(paymentMethod)||!List.of("ONE_WAY","ROUND_TRIP").contains(journeyType)||distanceKm<0||distanceKm>500)return "redirect:/customer?error=details";
  ServiceCity pc=cities.findById(pickupCityId).filter(ServiceCity::isActive).orElse(null), dc=cities.findById(destinationCityId).filter(ServiceCity::isActive).orElse(null);if(pc==null||dc==null||!pc.getPinCodes().contains(pickupPinCode)||!dc.getPinCodes().contains(destinationPinCode))return "redirect:/customer?error=locationPin";
  if(pc.getId().equals(dc.getId())&&pickupPinCode.equals(destinationPinCode)&&pickup.trim().equalsIgnoreCase(destination.trim()))return "redirect:/customer?error=locations";
  RideBooking r=new RideBooking();r.setCustomerId(u.getId());r.setCustomerName(u.getName());r.setCustomerMobile(u.getMobile());r.setPickup(pickup.trim());r.setDestination(destination.trim());r.setPickupCityId(pc.getId());r.setPickupCity(pc.getCity());r.setPickupPinCode(pickupPinCode);r.setDestinationCityId(dc.getId());r.setDestinationCity(dc.getCity());r.setDestinationPinCode(destinationPinCode);r.setJourneyType(journeyType);r.setReturnLegStatus("ROUND_TRIP".equals(journeyType)?"REQUESTED":"NOT_APPLICABLE");r.setCategory(category);r.setTripType(tripType);r.setPaymentMethod(paymentMethod);r.setEstimatedDistanceKm(distanceKm);r.setEstimatedFare(fareCalculator.estimate(fare(),category,distanceKm)*("ROUND_TRIP".equals(journeyType)?2:1));
  if("ROUND_TRIP".equals(journeyType)){try{LocalDateTime ret=LocalDateTime.parse(returnAt);if(ret.isBefore(LocalDateTime.now().plusMinutes(30))||ret.isAfter(LocalDateTime.now().plusDays(30)))return "redirect:/customer?error=returnDate";r.setReturnAt(ret);}catch(Exception ex){return "redirect:/customer?error=returnDate";}}
  if("SCHEDULED".equals(tripType)){try{LocalDateTime dt=LocalDateTime.parse(scheduledAt);if(dt.isBefore(LocalDateTime.now().plusMinutes(30))||dt.isAfter(LocalDateTime.now().plusDays(30)))return "redirect:/customer?error=schedule";r.setScheduledAt(dt);if("ROUND_TRIP".equals(journeyType)&&r.getReturnAt()!=null&&!r.getReturnAt().isAfter(dt))return "redirect:/customer?error=returnDate";}catch(Exception ex){return "redirect:/customer?error=schedule";}}
  r.setStatus("REQUESTED");rides.save(r);return "redirect:/customer?booked";
 }
 @GetMapping("/driver") String driver(Authentication a,Model m){UserAccount u=me(a);m.addAttribute("name",u.getName());m.addAttribute("user",u);m.addAttribute("partnerStatus",u.getStatus());m.addAttribute("available",u.isAvailable());m.addAttribute("rides",rides.findByStatusInOrderByCreatedAtDesc(List.of("REQUESTED","ACCEPTED","ASSIGNED","IN_PROGRESS")));m.addAttribute("myRides",rides.findByAssignedDriverIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("returnRides",rides.findAll().stream().filter(x->u.getId().equals(x.getReturnAssignedDriverId())).toList());m.addAttribute("openReturnRides",rides.findAll().stream().filter(x->!"CANCELLED".equals(x.getStatus())&&"ROUND_TRIP".equals(x.getJourneyType())&&"REQUESTED".equals(x.getReturnLegStatus())&&x.getReturnAssignedDriverId()==null&&x.getReturnAt()!=null).toList());m.addAttribute("vehicles",eligibleVehicles(u));List<RideBooking> mine=rides.findByAssignedDriverIdOrderByCreatedAtDesc(u.getId());m.addAttribute("completedCount",mine.stream().filter(x->"COMPLETED".equals(x.getStatus())).count());double outwardEarnings=mine.stream().filter(x->"COMPLETED".equals(x.getStatus())).mapToDouble(x->x.getFinalFare()-("ROUND_TRIP".equals(x.getJourneyType())?x.getReturnFinalFare():0)).sum();double returnEarnings=rides.findAll().stream().filter(x->u.getId().equals(x.getReturnAssignedDriverId())&&"COMPLETED".equals(x.getReturnLegStatus())).mapToDouble(RideBooking::getReturnFinalFare).sum();m.addAttribute("earnings",outwardEarnings+returnEarnings);List<PaymentRecord> driverPayments=payments.findAll().stream().filter(p->u.getId().equals(p.getDriverId())||u.getId().equals(p.getReturnDriverId())).toList();double netPaid=driverPayments.stream().filter(p->"PAID".equals(p.getStatus())).mapToDouble(p->(u.getId().equals(p.getDriverId())?p.getDriverNetAmount():0)+(u.getId().equals(p.getReturnDriverId())?p.getReturnDriverNetAmount():0)).sum();double netSettled=driverPayments.stream().filter(p->"PAID".equals(p.getStatus())).mapToDouble(p->(u.getId().equals(p.getDriverId())&&p.isSettled()?p.getDriverNetAmount():0)+(u.getId().equals(p.getReturnDriverId())&&p.isReturnSettled()?p.getReturnDriverNetAmount():0)).sum();m.addAttribute("netPaid",netPaid);m.addAttribute("netSettled",netSettled);m.addAttribute("netPendingSettlement",Math.max(0,netPaid-netSettled));return "driver";}
 private List<Vehicle> eligibleVehicles(UserAccount u){List<Vehicle> out=new ArrayList<>();for(Vehicle v:vehicles.findByStatus("APPROVED"))if(u.getId().equals(v.getOwnerId())||u.getId().equals(v.getAssignedDriverId()))out.add(v);return out;}
 @GetMapping("/locations/cities") @ResponseBody List<Map<String,Object>> activeCities(){return cities.findByActiveTrueOrderByCityAsc().stream().map(c->{Map<String,Object>x=new LinkedHashMap<>();x.put("id",c.getId());x.put("city",c.getCity());return x;}).toList();}
 @GetMapping("/locations/cities/{id}/pins") @ResponseBody List<String> cityPins(@PathVariable String id){return cities.findById(id).filter(ServiceCity::isActive).map(ServiceCity::getPinCodes).orElse(List.of());}
 @PostMapping("/driver/availability") String availability(Authentication a,@RequestParam boolean available){UserAccount u=me(a);if(!u.isMobileVerified()||!"APPROVED".equals(u.getStatus())){u.setAvailable(false);users.save(u);return "redirect:/driver?approvalPending";}u.setAvailable(available);users.save(u);return "redirect:/driver";}
 @PostMapping("/rides/{id}/accept") String accept(Authentication a,@PathVariable String id,@RequestParam String vehicleId){UserAccount u=me(a);if(!u.isAvailable()||!u.isMobileVerified()||!"APPROVED".equals(u.getStatus()))return "redirect:/driver?error=unavailable";if(hasActiveAssignment(u))return "redirect:/driver?error=active";
  RideBooking r=rides.findById(id).orElseThrow();if(!"REQUESTED".equals(r.getStatus()))return "redirect:/driver?error=taken";Vehicle v=eligibleVehicles(u).stream().filter(x->x.getId().equals(vehicleId)&&x.getCategory().equals(r.getCategory())).findFirst().orElse(null);if(v==null)return "redirect:/driver?error=vehicle";
  r.setAssignedDriverId(u.getId());r.setAssignedDriverName(u.getName());r.setAssignedVehicleId(v.getId());r.setAssignedVehicleNumber(v.getRegistrationNumber());if("ROUND_TRIP".equals(r.getJourneyType())&&r.getReturnAssignedDriverId()==null){r.setReturnAssignedDriverId(u.getId());r.setReturnAssignedDriverName(u.getName());r.setReturnAssignedVehicleId(v.getId());r.setReturnAssignedVehicleNumber(v.getRegistrationNumber());}r.setPickupOtp(String.format("%06d",random.nextInt(1_000_000)));r.addStatusEvent("REQUESTED","ACCEPTED",u.getName(),"Driver accepted ride");r.setStatus("ACCEPTED");rides.save(r);return "redirect:/driver?accepted";
 }
 @PostMapping("/rides/{id}/status") String updateStatus(Authentication a,@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String pickupOtp,@RequestParam(required=false,defaultValue="0") double actualDistanceKm,@RequestParam(required=false,defaultValue="0") int actualDurationMinutes,@RequestParam(required=false,defaultValue="0") int waitingMinutes){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getAssignedDriverId()))return "redirect:/driver?error=denied";
  if("IN_PROGRESS".equals(status)){if(!("ACCEPTED".equals(r.getStatus())||"ASSIGNED".equals(r.getStatus()))||pickupOtp==null||!pickupOtp.equals(r.getPickupOtp()))return "redirect:/driver?error=otp";r.setTripStartedAt(Instant.now());r.addStatusEvent(r.getStatus(),"IN_PROGRESS",u.getName(),"Driver verified pickup OTP");r.setStatus("IN_PROGRESS");}
  else if("COMPLETED".equals(status)){if(!"IN_PROGRESS".equals(r.getStatus())||actualDistanceKm<0||actualDistanceKm>500||actualDurationMinutes<0||actualDurationMinutes>1440||waitingMinutes<0||waitingMinutes>1440)return "redirect:/driver?error=tripdata";r.setActualDistanceKm(actualDistanceKm);r.setActualDurationMinutes(actualDurationMinutes);r.setWaitingMinutes(waitingMinutes);r.setFinalFare(fareCalculator.finalFare(fare(),r.getCategory(),actualDistanceKm,actualDurationMinutes,waitingMinutes,r.getTripStartedAt()==null?null:LocalDateTime.ofInstant(r.getTripStartedAt(),ZoneId.systemDefault())));r.setTripCompletedAt(Instant.now());r.setPickupOtp(null);r.addStatusEvent(r.getStatus(),"COMPLETED",u.getName(),"Driver completed trip");r.setStatus("COMPLETED");}
  else return "redirect:/driver";rides.save(r);return "redirect:/driver?updated";
 }
 @PostMapping("/rides/{id}/return/accept") String acceptReturn(Authentication a,@PathVariable String id,@RequestParam String vehicleId){UserAccount u=me(a);if(!u.isAvailable()||!u.isMobileVerified()||!"APPROVED".equals(u.getStatus()))return "redirect:/driver?error=unavailable";if(hasActiveAssignment(u))return "redirect:/driver?error=active";RideBooking r=rides.findById(id).orElseThrow();if("CANCELLED".equals(r.getStatus())||!"ROUND_TRIP".equals(r.getJourneyType())||!"REQUESTED".equals(r.getReturnLegStatus())||r.getReturnAt()==null)return "redirect:/driver?error=returnTaken";Vehicle v=eligibleVehicles(u).stream().filter(x->x.getId().equals(vehicleId)&&x.getCategory().equals(r.getCategory())).findFirst().orElse(null);if(v==null)return "redirect:/driver?error=vehicle";r.setReturnAssignedDriverId(u.getId());r.setReturnAssignedDriverName(u.getName());r.setReturnAssignedVehicleId(v.getId());r.setReturnAssignedVehicleNumber(v.getRegistrationNumber());r.setReturnPickupOtp(String.format("%06d",random.nextInt(1_000_000)));r.addStatusEvent("RETURN_REQUESTED","RETURN_ACCEPTED",u.getName(),"Driver accepted return leg");r.setReturnLegStatus("ACCEPTED");rides.save(r);return "redirect:/driver?returnAccepted";}
 @PostMapping("/rides/{id}/return/confirm") String confirmPreferredReturn(Authentication a,@PathVariable String id){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getReturnAssignedDriverId())||!"ROUND_TRIP".equals(r.getJourneyType())||!"COMPLETED".equals(r.getStatus())||!"REQUESTED".equals(r.getReturnLegStatus())||r.getReturnAt()==null||r.getReturnAt().isAfter(LocalDateTime.now())||!u.isMobileVerified()||!"APPROVED".equals(u.getStatus())||!u.isAvailable())return "redirect:/driver?error=returnNotReady";Vehicle v=vehicles.findById(r.getReturnAssignedVehicleId()).orElse(null);if(v==null||!"APPROVED".equals(v.getStatus())||!r.getCategory().equals(v.getCategory()))return "redirect:/driver?error=vehicle";r.setReturnPickupOtp(String.format("%06d",random.nextInt(1_000_000)));r.addStatusEvent("RETURN_REQUESTED","RETURN_ACCEPTED",u.getName(),"Driver confirmed preferred return assignment");r.setReturnLegStatus("ACCEPTED");rides.save(r);return "redirect:/driver?returnAccepted";}
 @PostMapping("/rides/{id}/return/status") String returnStatus(Authentication a,@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String pickupOtp,@RequestParam(required=false,defaultValue="0") double actualDistanceKm){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getReturnAssignedDriverId()))return "redirect:/driver?error=denied";if("IN_PROGRESS".equals(status)){if(!"COMPLETED".equals(r.getStatus())||r.getReturnAt()==null||r.getReturnAt().isAfter(LocalDateTime.now())||!"ACCEPTED".equals(r.getReturnLegStatus())||pickupOtp==null||!pickupOtp.equals(r.getReturnPickupOtp()))return "redirect:/driver?error=otp";r.setReturnTripStartedAt(Instant.now());r.addStatusEvent("RETURN_ACCEPTED","RETURN_IN_PROGRESS",u.getName(),"Return pickup OTP verified");r.setReturnLegStatus("IN_PROGRESS");}else if("COMPLETED".equals(status)){if(!"IN_PROGRESS".equals(r.getReturnLegStatus())||actualDistanceKm<=0||actualDistanceKm>1000)return "redirect:/driver?error=tripdata";r.setReturnActualDistanceKm(actualDistanceKm);r.setReturnFinalFare(fareCalculator.estimate(fare(),r.getCategory(),actualDistanceKm));r.setReturnTripCompletedAt(Instant.now());r.setReturnPickupOtp(null);r.addStatusEvent("RETURN_IN_PROGRESS","RETURN_COMPLETED",u.getName(),"Return journey completed");r.setReturnLegStatus("COMPLETED");r.setFinalFare(r.getFinalFare()+r.getReturnFinalFare());}else return "redirect:/driver";rides.save(r);return "redirect:/driver?returnUpdated";}
 @PostMapping("/driver/location") String location(Authentication a,@RequestParam double latitude,@RequestParam double longitude){UserAccount u=me(a);if(latitude < -90||latitude>90||longitude < -180||longitude>180)return "redirect:/driver?error=location";for(RideBooking r:rides.findByAssignedDriverIdOrderByCreatedAtDesc(u.getId()))if("IN_PROGRESS".equals(r.getStatus())||"ACCEPTED".equals(r.getStatus())||"ASSIGNED".equals(r.getStatus())){r.setCurrentDriverLatitude(latitude);r.setCurrentDriverLongitude(longitude);r.setDriverLocationUpdatedAt(Instant.now());rides.save(r);}return "redirect:/driver?location=updated";}
 @GetMapping("/rides/{id}/location") @ResponseBody ResponseEntity<Map<String,Object>> locationForCustomer(Authentication a,@PathVariable String id){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(!u.getId().equals(r.getCustomerId()))return ResponseEntity.status(403).build();Map<String,Object> data=new LinkedHashMap<>();data.put("status",r.getStatus());data.put("latitude",r.getCurrentDriverLatitude());data.put("longitude",r.getCurrentDriverLongitude());data.put("updatedAt",r.getDriverLocationUpdatedAt());data.put("driver",r.getAssignedDriverName());return ResponseEntity.ok(data);}
 @GetMapping("/admin/rides") String adminRides(Model m){m.addAttribute("rides",rides.findAll());m.addAttribute("drivers",users.findByRoleAndStatusAndMobileVerified("DRIVER","APPROVED",true));m.addAttribute("vehicles",vehicles.findByStatus("APPROVED"));return "admin-rides";}
 @PostMapping("/admin/rides/{id}/cancel") String cancel(@PathVariable String id){RideBooking r=rides.findById(id).orElseThrow();if(!List.of("COMPLETED","CANCELLED").contains(r.getStatus())){if(List.of("ACCEPTED","IN_PROGRESS").contains(r.getStatus()))r.setCancellationCharge(fare().getCancellationFee());String old=r.getStatus();r.setStatus("CANCELLED");r.addStatusEvent(old,"CANCELLED","ADMIN","Admin cancelled ride");if("ROUND_TRIP".equals(r.getJourneyType())&&List.of("REQUESTED","ACCEPTED").contains(r.getReturnLegStatus()))r.setReturnLegStatus("CANCELLED");rides.save(r);}return "redirect:/admin/rides";}
 @PostMapping("/rides/{id}/cancel") String customerCancel(Authentication a,@PathVariable String id){UserAccount u=me(a);RideBooking r=rides.findById(id).orElseThrow();if(u.getId().equals(r.getCustomerId())&&List.of("REQUESTED","ACCEPTED","ASSIGNED").contains(r.getStatus())){if("ACCEPTED".equals(r.getStatus()))r.setCancellationCharge(fare().getCancellationFee());r.setPickupOtp(null);r.addStatusEvent(r.getStatus(),"CANCELLED",u.getName(),"Customer cancelled booking");r.setStatus("CANCELLED");rides.save(r);}return "redirect:/customer";}
 @PostMapping("/admin/rides/{id}/return/assign") String adminAssignReturn(@PathVariable String id,@RequestParam String driverId,@RequestParam String vehicleId){RideBooking r=rides.findById(id).orElseThrow();UserAccount d=users.findById(driverId).orElse(null);Vehicle v=vehicles.findById(vehicleId).orElse(null);boolean sameOutward=d!=null&&d.getId().equals(r.getAssignedDriverId());if(!"ROUND_TRIP".equals(r.getJourneyType())||"CANCELLED".equals(r.getStatus())||("IN_PROGRESS".equals(r.getReturnLegStatus())||"COMPLETED".equals(r.getReturnLegStatus()))||d==null||v==null||(!d.isAvailable()&&!sameOutward)||hasActiveAssignment(d)||!"DRIVER".equals(d.getRole())||!"APPROVED".equals(d.getStatus())||!d.isMobileVerified()||!d.getId().equals(v.getOwnerId())&&!d.getId().equals(v.getAssignedDriverId())||!"APPROVED".equals(v.getStatus())||!r.getCategory().equals(v.getCategory()))return "redirect:/admin/rides?error=returnAssign";r.setReturnAssignedDriverId(d.getId());r.setReturnAssignedDriverName(d.getName());r.setReturnAssignedVehicleId(v.getId());r.setReturnAssignedVehicleNumber(v.getRegistrationNumber());r.setReturnPickupOtp(String.format("%06d",random.nextInt(1_000_000)));String oldReturn=r.getReturnLegStatus();r.setReturnLegStatus("ACCEPTED");r.addStatusEvent("RETURN_"+oldReturn,"RETURN_ACCEPTED","ADMIN","Admin assigned return driver and vehicle");rides.save(r);return "redirect:/admin/rides?returnAssigned";}
 @PostMapping("/admin/rides/{id}/assign-outward") String adminAssignOutward(@PathVariable String id,@RequestParam String driverId,@RequestParam String vehicleId,@RequestParam(required=false) String note){RideBooking r=rides.findById(id).orElseThrow();UserAccount d=users.findById(driverId).orElse(null);Vehicle v=vehicles.findById(vehicleId).orElse(null);boolean sameCurrent=d!=null&&d.getId().equals(r.getAssignedDriverId());if(d==null||v==null||!"DRIVER".equals(d.getRole())||!"APPROVED".equals(d.getStatus())||!d.isMobileVerified()||!d.isAvailable()||(!sameCurrent&&hasActiveAssignment(d))||!"APPROVED".equals(v.getStatus())||!r.getCategory().equals(v.getCategory())||(!d.getId().equals(v.getOwnerId())&&!d.getId().equals(v.getAssignedDriverId()))||List.of("IN_PROGRESS","COMPLETED","CANCELLED").contains(r.getStatus()))return "redirect:/admin/rides?error=assign";String old=r.getStatus();r.setAssignedDriverId(d.getId());r.setAssignedDriverName(d.getName());r.setAssignedVehicleId(v.getId());r.setAssignedVehicleNumber(v.getRegistrationNumber());r.setPickupOtp(String.format("%06d",random.nextInt(1_000_000)));r.setStatus("ACCEPTED");r.addStatusEvent(old,"ACCEPTED","ADMIN",note==null?"Admin assigned outward driver and vehicle":note);rides.save(r);return "redirect:/admin/rides?assigned";}
 @PostMapping("/admin/rides/{id}/status") String adminTripStatus(@PathVariable String id,@RequestParam String status,@RequestParam String reason){RideBooking r=rides.findById(id).orElseThrow();if(reason==null||reason.isBlank()||reason.length()>300||!List.of("REQUESTED","ACCEPTED","ASSIGNED","CANCELLED").contains(status)||List.of("IN_PROGRESS","COMPLETED","CANCELLED").contains(r.getStatus())&&!("CANCELLED".equals(status)&&!"CANCELLED".equals(r.getStatus())))return "redirect:/admin/rides?error=status";String old=r.getStatus();boolean validTransition=("REQUESTED".equals(old)&&List.of("REQUESTED","ACCEPTED","ASSIGNED","CANCELLED").contains(status))||("ACCEPTED".equals(old)&&List.of("ACCEPTED","ASSIGNED","CANCELLED").contains(status))||("ASSIGNED".equals(old)&&List.of("ASSIGNED","CANCELLED").contains(status))||("IN_PROGRESS".equals(old)&&"CANCELLED".equals(status));if(!validTransition)return "redirect:/admin/rides?error=status";if(("ACCEPTED".equals(status)||"ASSIGNED".equals(status))&&r.getAssignedDriverId()==null)return "redirect:/admin/rides?error=status";if("CANCELLED".equals(status)){r.setCancellationCharge(List.of("ACCEPTED","ASSIGNED","IN_PROGRESS").contains(old)?fare().getCancellationFee():0);r.setPickupOtp(null);r.setReturnPickupOtp(null);if("ROUND_TRIP".equals(r.getJourneyType())&&List.of("REQUESTED","ACCEPTED").contains(r.getReturnLegStatus()))r.setReturnLegStatus("CANCELLED");}r.setStatus(status);r.addStatusEvent(old,status,"ADMIN",reason.trim());rides.save(r);return "redirect:/admin/rides?statusUpdated";}
 @PostMapping("/admin/rides/{id}/return/status") String adminReturnStatus(@PathVariable String id,@RequestParam String status,@RequestParam String reason){RideBooking r=rides.findById(id).orElseThrow();if(!"ROUND_TRIP".equals(r.getJourneyType())||reason==null||reason.isBlank()||reason.length()>300||!List.of("REQUESTED","ACCEPTED","CANCELLED").contains(status)||List.of("IN_PROGRESS","COMPLETED","CANCELLED").contains(r.getReturnLegStatus()))return "redirect:/admin/rides?error=returnStatus";if("ACCEPTED".equals(status)&&r.getReturnAssignedDriverId()==null)return "redirect:/admin/rides?error=returnStatus";String old=r.getReturnLegStatus();r.setReturnLegStatus(status);if("CANCELLED".equals(status))r.setReturnPickupOtp(null);r.addStatusEvent("RETURN_"+old,"RETURN_"+status,"ADMIN",reason.trim());rides.save(r);return "redirect:/admin/rides?statusUpdated";}
 @GetMapping("/admin/fares") String fareSettings(Model m){m.addAttribute("fare",fare());return "admin-fares";}
 @PostMapping("/admin/fares") String saveFares(@RequestParam double baseFare,@RequestParam double perKm,@RequestParam double perMinute,@RequestParam double minimumFare,@RequestParam double waitingPerMinute,@RequestParam double nightMultiplier,@RequestParam int nightStartHour,@RequestParam int nightEndHour,@RequestParam double cancellationFee,@RequestParam double carMultiplier,@RequestParam double autoMultiplier,@RequestParam double bikeMultiplier,@RequestParam double otherMultiplier,@RequestParam(defaultValue="15") double individualCommissionPercent,@RequestParam(defaultValue="10") double fleetCommissionPercent){if(baseFare<0||baseFare>10000||perKm<0||perKm>1000||perMinute<0||perMinute>500||minimumFare<0||minimumFare>10000||waitingPerMinute<0||waitingPerMinute>500||nightMultiplier<1||nightMultiplier>5||nightStartHour<0||nightStartHour>23||nightEndHour<0||nightEndHour>23||cancellationFee<0||cancellationFee>5000||!validMultiplier(carMultiplier)||!validMultiplier(autoMultiplier)||!validMultiplier(bikeMultiplier)||!validMultiplier(otherMultiplier)||individualCommissionPercent<0||individualCommissionPercent>50||fleetCommissionPercent<0||fleetCommissionPercent>50)return "redirect:/admin/fares?error=values";FareRule f=fare();f.setBaseFare(baseFare);f.setPerKm(perKm);f.setPerMinute(perMinute);f.setMinimumFare(minimumFare);f.setWaitingPerMinute(waitingPerMinute);f.setNightMultiplier(nightMultiplier);f.setNightStartHour(nightStartHour);f.setNightEndHour(nightEndHour);f.setCancellationFee(cancellationFee);f.setCarMultiplier(carMultiplier);f.setAutoMultiplier(autoMultiplier);f.setBikeMultiplier(bikeMultiplier);f.setOtherMultiplier(otherMultiplier);f.setIndividualCommissionPercent(individualCommissionPercent);f.setFleetCommissionPercent(fleetCommissionPercent);f.touch();fareRules.save(f);return "redirect:/admin/fares?saved";}
 private boolean validMultiplier(double v){return v>=0.1&&v<=5;}
}
